#!/usr/bin/env Rscript

# Re-runs one identifiable-setting task (or all 80 default tasks). The Wald
# results are generated by this script together with A-ERM and ERM.
root <- normalizePath(".")
out <- file.path(root, "generated", "identifiable")
dir.create(out, recursive = TRUE, showWarnings = FALSE)
Sys.setenv(IVITR_IDENT_DIR = out)
source(file.path(root, "code", "simulations", "test_ident.R"))
